import{R as t,e as o,f as n,U as i}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Google Sheets","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/miscellaneous/google-sheets.md","filePath":"integrations/miscellaneous/google-sheets.md","lastUpdated":1775908585000}'),r={name:"integrations/miscellaneous/google-sheets.md"};function s(l,e,a,g,h,c){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="google-sheets" tabindex="-1">Google Sheets <a class="header-anchor" href="#google-sheets" aria-label="Permalink to &quot;Google Sheets&quot;">​</a></h1><p>Follow the below steps to connect to the Google Sheets API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Miscellaneous</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Google Sheets as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-google-sheets-api" tabindex="-1">Step 2. Connect to the Google Sheets API <a class="header-anchor" href="#step-2-connect-to-the-google-sheets-api" aria-label="Permalink to &quot;Step 2. Connect to the Google Sheets API&quot;">​</a></h3><ol><li>Go to the <a href="https://console.cloud.google.com/apis/credentials" target="_blank">Google API Console</a>.</li><li>Select an existing project or create a new one.</li><li>Go to the <strong>APIs &amp; Services</strong> → <strong>Library</strong> and enable the <strong>Google Drive API</strong> and <strong>Google Sheets API</strong> for the project.</li><li>Next, go to the <strong>APIs &amp; Services</strong> → <strong>Credentials</strong> section.</li><li>Click <strong>Create Credentials</strong> → <strong>OAuth client ID</strong>. <ol><li>On the following page, select the <strong>Application Type</strong> as <strong>Web application</strong>.</li><li>Provide a suitable <strong>Name</strong> so you can identify it in your Google account. This is not required by Formie.</li><li>Under the <strong>Authorized JavaScript origins</strong>, click <strong>Add URI</strong> and enter your project&#39;s Site URL.</li><li>Under the <strong>Authorized redirect URIs</strong>, click <strong>Add URI</strong> and enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Then click the <strong>Create</strong> button.</li></ol></li><li>Once created, a popup will appear with your OAuth credentials. Copy the <strong>Client ID</strong> and <strong>Client Secret</strong> values and paste into the fields in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Google, where you must approve Formie to access your Google account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
